# Fact sheet for the Java REST API contract audit. Usage: api_facts.py <repo-root> <source-dir>
import os
import re
import sys

from javasrc import Sheet, java_files, line_of, methods, strip_java

MAPPING = re.compile(r'@(Get|Post|Put|Delete|Patch|Request)Mapping\b(?:\s*\(((?:[^()]|\([^()]*\))*)\))?')
WRITE_NAME = re.compile(r'^(create|delete|update|save|remove|add|execute|run|start|stop|trigger|reset|cancel|approve|import|install|apply)')
READ_NAME = re.compile(r'^(get|list|find|load|fetch|show)(?!.*(?:And|Or)(?:Create|Save))')


def mapping_paths(args, raw_args):
    """Paths of a mapping annotation, read from the raw text (string literals are blanked in the stripped one)."""
    if not raw_args:
        return ['']
    paths = re.findall(r'"([^"]*)"', raw_args)
    named = re.search(r'\b(?:value|path)\s*=\s*\{?([^}]*)\}?', raw_args)
    if named:
        paths = re.findall(r'"([^"]*)"', named.group(1)) or paths
    elif re.search(r'\b\w+\s*=', raw_args) and not raw_args.strip().startswith('"'):
        paths = []
    return paths or ['']


def main():
    base = os.path.abspath(sys.argv[1])
    src_root = os.path.join(base, sys.argv[2])
    sheet = Sheet(cap=40)
    files = controllers = handlers = handlers_doc = advice = 0
    entity_names = set()
    sources = []

