# Fact sheet for the Java readability/design audit. Usage: design_facts.py <repo-root> <source-dir>
import os
import re
import sys

from javasrc import Sheet, java_files, line_of, match_brace, match_paren, methods, strip_java

TYPE_GETTER = r'(?:getType|type|getKind|kind|getBlockType|getCategory|category|getStatus|status|getMode|mode)\(\)'
CONST_LABEL = re.compile(r'\bcase\s+([A-Z][A-Z0-9_]+)\s*(?:->|:|,)')
COLLABORATOR_NEW = re.compile(r'\bnew\s+([A-Z]\w*(?:Service|Repository|Client|Executor|Manager|Gateway|Provider|Registry|Handler))\s*\(')
COMPONENT = re.compile(r'@(Service|Component|RestController|Controller|Repository)\b')
# Walking untyped data (JSON trees, collections) and classifying exceptions by type is normal, not a design smell.
NEUTRAL_TYPES = re.compile(r'^(List|Map|Set|Collection|Iterable|String|CharSequence|Number|Integer|Long|Double|Float|Boolean|'
                           r'Object|JsonNode|ObjectNode|ArrayNode|TextNode|NumericNode|BooleanNode|Optional|byte|\w+Exception|\w+Error|Throwable)$')


def main():
    base = os.path.abspath(sys.argv[1])
    src_root = os.path.join(base, sys.argv[2])
    sheet = Sheet(cap=40)
    files = 0
    switch_groups = {}

    print('## FAKTENBLATT')
    print('# Measured deterministically (regex over the source, comments and strings removed).')
    print('# TREFFER lines are candidates with a location, not proof; check each one in the source.')
    print('')
    if not os.path.isdir(src_root):
        print('NICHT GEMESSEN: java_files_scanned (source directory %s missing)' % sys.argv[2])
        return

    for path in java_files(src_root):
        rel = os.path.relpath(path, base)
        try:
            raw = open(path, encoding='utf-8', errors='replace').read()
        except OSError:
            continue
        files += 1
        s = strip_java(raw)
        meths = methods(s)

        # switches over a type/kind/status getter, and switches over constant labels (for scattered switches)
        for sm in re.finditer(r'\bswitch\s*\(', s):
            p_close = match_paren(s, sm.end() - 1)
            subject = re.sub(r'\s+', '', s[sm.end():p_close])
            b_open = s.find('{', p_close)
            if b_open < 0:
                continue
            body = s[b_open:match_brace(s, b_open)]
            labels = frozenset(CONST_LABEL.findall(body))
            ln = line_of(s, sm.start())
            if re.search(TYPE_GETTER + '$', subject) and len(labels) >= 3:
                sheet.hit('type_switch', '%s:%d switch (%s) with %d cases' % (rel, ln, subject[:60], len(labels)))
            if len(labels) >= 3:
                switch_groups.setdefault(labels, []).append('%s:%d' % (rel, ln))

        for m in meths:
            body = s[m['start']:m['end']]
            # instanceof chains: three or more type tests in if/else-if conditions of one method
            tests = [t for t in re.findall(r'\bif\s*\([^{;]*\binstanceof\s+([A-Z]\w*)', body) if not NEUTRAL_TYPES.match(t)]
            if len(set(tests)) >= 3 and m['name'] not in ('equals', 'compareTo'):
                sheet.hit('instanceof_chain', '%s:%d %s() tests %d types with instanceof (%s)' % (
                    rel, m['line'], m['name'], len(set(tests)), ', '.join(sorted(set(tests))[:5])))
            # if/else-if chains comparing the same type getter against constants
            cmp = re.findall(r'\bif\s*\(\s*[\w.]*' + TYPE_GETTER + r'\s*==\s*[\w.]+|\bif\s*\(\s*[\w.]+\.equals\(\s*[\w.]*' + TYPE_GETTER, body)
            if len(cmp) >= 3:
                sheet.hit('type_switch', '%s:%d %s() branches %d times on a type getter with if' % (rel, m['line'], m['name'], len(cmp)))
            # overrides that only refuse (Liskov/interface segregation)
            if '@Override' in m['annos'] and re.fullmatch(r'\{\s*throw\s+new\s+UnsupportedOperationException\s*\([^;]*\)\s*;\s*', body):
                sheet.hit('refused_override', '%s:%d %s() only overrides with UnsupportedOperationException' % (rel, m['line'], m['name']))
            # empty overrides of non-void-ish interface methods are a weaker signal; skipped on purpose

        # Spring components that build their collaborators themselves (hidden dependency, not injectable)
        if COMPONENT.search(s):
            for nm in COLLABORATOR_NEW.finditer(s):
                if nm.group(1).endswith('Exception'):
                    continue
                enclosing = [mm for mm in meths if mm['start'] <= nm.start() <= mm['end']]
                if enclosing and re.search(r'@Bean\b', enclosing[-1]['annos']):
                    continue
                sheet.hit('hidden_dependency', '%s:%d new %s(...) in a Spring component' % (rel, line_of(s, nm.start()), nm.group(1)))

    # the same case-label set switched in three or more places: one change touches all of them
    # clusters of switches sharing at least three case labels across files (union-find over the label sets)
    entries = [(labels, site) for labels, sites in switch_groups.items() for site in sites]
    parent = list(range(len(entries)))

    def find(i):
        while parent[i] != i:
            parent[i] = parent[parent[i]]
            i = parent[i]
        return i
    for i in range(len(entries)):
        for j in range(i + 1, len(entries)):
            if len(entries[i][0] & entries[j][0]) >= 3:
                parent[find(i)] = find(j)
    clusters = {}
    for i, (labels, site) in enumerate(entries):
        clusters.setdefault(find(i), []).append((labels, site))
    for members in sorted(clusters.values(), key=lambda m: -len(m)):
        files_in = {site.split(':')[0] for _, site in members}
        if len(files_in) < 3:
            continue
        common = frozenset.intersection(*[l for l, _ in members]) or max((l for l, _ in members), key=len)
        sheet.hit('scattered_switch', 'cases {%s} in %d files: %s' % (
            ', '.join(sorted(common)[:6]), len(files_in), '; '.join(site for _, site in members[:6])))

    print('FAKT java_files_scanned: %d' % files)
    kinds = ['type_switch', 'scattered_switch', 'instanceof_chain', 'refused_override', 'hidden_dependency']
    sheet.emit(kinds)
    print('')
    print('## PFLICHTFELDER')
    print('PFLICHT-FAKTEN: java_files_scanned pmd_design_findings type_switch_count instanceof_chain_count')


if __name__ == '__main__':
    main()
